awk 'BEGIN{zpe=""};/Zero-point vibrational energy/ {for(i=1;i<=NF;i++){if($i ~ /^[-+]?[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?$/){zpe=$i;break}}; if(zpe=="" && match($0,/Zero-point vibrational energy[[:space:]]*=[[:space:]]*([+-]?[0-9]*\.?[0-9]+([eE][+-]?[0-9]+)?)/,m)){zpe=m[1]}; if(zpe!=""){print zpe; exit}};/Zero-point correction=/ {if(match($0,/Zero-point correction=[[:space:]]*([+-]?[0-9]*\.?[0-9]+([eE][+-]?[0-9]+)?)/,m)){print m[1]; exit}};END{if(zpe!="") print zpe}' $1
